<script setup>
import {ref,computed,onMounted} from 'vue';import {supabase} from '../lib/supabase.js'
const rows=ref([]),query=ref(''),loading=ref(true),error=ref(''),selected=ref(null)
const filtered=computed(()=>{const q=query.value.toLowerCase();return rows.value.filter(r=>`${r.title||''}${r.source_name||''}`.toLowerCase().includes(q))})
onMounted(async()=>{const {data,error:e}=await supabase.from('private_library_documents').select('*').order('updated_at',{ascending:false});if(e)error.value=e.message;else rows.value=data||[];loading.value=false})
</script>
<template><div class="page"><div class="page-head"><div><h2>私人资料库</h2><p>Owner 专属文档索引与结构化内容浏览。</p></div></div><div v-if="error" class="notice">{{error}}</div><section class="card"><div class="toolbar"><input v-model="query" placeholder="搜索文档标题或来源"></div><div v-if="loading" class="loading">正在读取资料…</div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>文档</th><th>来源</th><th>类型</th><th>内容量</th><th></th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td><b>{{row.title}}</b></td><td>{{row.source_name||'—'}}</td><td><span class="badge">{{row.kind||row.category||'文档'}}</span></td><td>{{row.content_count||'—'}}</td><td><button class="btn secondary" @click="selected=row">查看</button></td></tr></tbody></table><div v-if="!filtered.length" class="empty">暂无匹配资料</div></div></section><div v-if="selected" class="modal-layer" @click.self="selected=null"><article class="modal"><header><h2>{{selected.title}}</h2><button @click="selected=null">×</button></header><pre style="white-space:pre-wrap;font:12px/1.8 monospace">{{JSON.stringify(selected.content,null,2)}}</pre></article></div></div></template>
